def text(value):
    return {"kind": "text", "value":str(value)}


def symbol(kind):
    return {"kind": kind}


LINE = symbol("line")
SOFTLINE = symbol("softline")
HARDLINE = symbol("hardline")
BREAK_PARENT = symbol("break_parent")


def suffix(value):
    return {"kind": "suffix", "value": value}


def if_break(broken, flat):
    return {"kind": "if_break", "broken": broken, "flat": flat}


def concat(*parts):
    elements = []

    def add(part):
        if part is None:
            return
        if isinstance(part, str):
            part = text(part)
        if isinstance(part, (list, tuple)):
            for child in part:
                add(child)
            return
        if part["kind"] == "concat":
            for child in part["items"]:
                add(child)
        elif part["kind"] == "text":
            value = part["value"]
            if not value:
                return
            if elements and elements[-1]["kind"] == "text":
                elements[-1] = text(elements[-1]["value"] + value)
            else:
                elements.append(text(value))
        else:
            elements.append(part)

    for part in parts:
        add(part)
    if not elements:
        return text("")
    if len(elements) == 1:
        return elements[0]
    return {"kind": "concat", "items": elements}


def force_broken(document):
    kind = document["kind"]
    if kind in ("hardline", "break_parent"):
        return True
    if kind == "concat":
        return any(force_broken(child) for child in document["items"])
    if kind in ("group", "nest", "align"):
        return force_broken(document["child"])
    return False


def group(child):
    normalized = concat(child)
    return {
        "kind": "group", "child": normalized,
        "forced": force_broken(normalized), "mode": None,
    }


def nest(amount, child):
    return {"kind": "nest", "amount": amount, "child": concat(child)}


def align(child):
    return {"kind": "align", "child": concat(child)}


def all_groups(document):
    if document["kind"] == "group":
        yield document
        yield from all_groups(document["child"])
    elif document["kind"] in ("nest", "align"):
        yield from all_groups(document["child"])
    elif document["kind"] == "concat":
        for child in document["items"]:
            yield from all_groups(child)

KEYWORDS = set(
    "int float bool string void if else while for return break continue "
    "true false switch case default".split()
)
TYPES = {"int", "float", "bool", "string", "void"}
DOUBLE = {"<=", ">=", "==", "!=", "&&", "||", "+=", "-=", "*=", "/=", "%="}
SINGLE = set("+-*/%<>=!()[]{},;.?:")
ASSIGNMENT = {"=", "+=", "-=", "*=", "/=", "%="}


class SourceError(Exception):
    def __init__(self, line, column, message):
        self.line = line
        self.column = column
        self.message = message
        super().__init__(f"{line}:{column}: {message}")


def token(kind, text, line, column, blank, index):
    return {
        "kind": kind, "text": text, "line": line, "column": column,
        "blank": blank, "index": index, "leading": [],
        "trailing": [], "allowed": False, "trailing_comma": False,
    }


def lexical_analysis(lines):
    tokens = []
    comments = []
    items = []
    previous_line = 0
    for line_no, line in enumerate(lines, 1):
        column = 0
        while column < len(line):
            ch = line[column]
            if ch == " ":
                column += 1
                continue
            start = column
            kind = ""
            if line.startswith("//", column):
                kind = "line_comment"
                column = len(line)
                text = line[start:].rstrip(" ")
            elif line.startswith("/*", column):
                end = line.find("*/", column + 2)
                if end < 0:
                    raise SourceError(line_no, column + 1, "unterminated comment")
                kind = "block_comment"
                column = end + 2
                text = line[start:column]
            elif ch.isascii() and (ch.isalpha() or ch == "_"):
                column += 1
                while column < len(line) and line[column].isascii() and (
                        line[column].isalnum() or line[column] == "_"):
                    column += 1
                text = line[start:column]
                kind = "keyword" if text in KEYWORDS else "identifier"
            elif "0" <= ch <= "9":
                column += 1
                while column < len(line) and line[column].isdigit():
                    column += 1
                if column + 1 < len(line) and line[column] == "." and (
                        "0" <= line[column + 1] <= "9"):
                    column += 2
                    while column < len(line) and "0" <= line[column] <= "9":
                        column += 1
                text = line[start:column]
                kind = "number"
            elif ch == '"':
                column += 1
                closed = False
                while column < len(line):
                    if line[column] == "\\":
                        column += 2
                    elif line[column] == '"':
                        column += 1
                        closed = True
                        break
                    else:
                        column += 1
                if not closed:
                    raise SourceError(line_no, start + 1, "unterminated string")
                text = line[start:column]
                kind = "string"
            elif line[column:column + 2] in DOUBLE:
                column += 2
                text = line[start:column]
                kind = "symbol"
            elif ch in SINGLE:
                column += 1
                text = ch
                kind = "symbol"
            else:
                raise SourceError(line_no, start + 1, f"unexpected character '{ch}'")

            entry = {
                "kind": kind, "text": text, "line": line_no,
                "column": start + 1, "blank": max(0, line_no - previous_line - 1),
            }
            previous_line = line_no
            items.append(entry)
            if kind.endswith("_comment"):
                comments.append(entry)
            else:
                tokens.append(entry)
    for index, entry in enumerate(tokens):
        entry.update({
            "index": index, "leading": [], "trailing": [],
            "allowed": False, "trailing_comma": False,
        })
    end = token("end", "", len(lines) + 1, 1, 0, len(tokens))
    end["allowed"] = True
    tokens.append(end)
    return tokens, comments, items


def attach_comments(tokens, comments, items):
    token_order = [entry for entry in items if not entry["kind"].endswith("_comment")]
    position = {id(entry): index for index, entry in enumerate(items)}
    for comment in comments:
        i = position[id(comment)]
        before = next((entry for entry in reversed(items[:i])
                       if not entry["kind"].endswith("_comment")), None)
        after = next((entry for entry in items[i + 1:]
                      if not entry["kind"].endswith("_comment")), None)
        following = items[i + 1] if i + 1 < len(items) else None
        comment["own_line"] = (
            comment["kind"] == "line_comment" or following is None
            or following["line"] > comment["line"]
        )
        if (before is not None and before["line"] == comment["line"]
                and (after is None or after["line"] > comment["line"])):
            before["trailing"].append(comment)
        else:
            (after if after is not None else tokens[-1])["leading"].append(comment)
    return tokens


def first_comment_blank(entry):
    if entry["leading"]:
        return entry["leading"][0]["blank"]
    return entry["blank"]

from pathlib import Path

from doc_builder import (
    BREAK_PARENT, HARDLINE, LINE, SOFTLINE, align, all_groups,
    concat, group, if_break, nest, suffix, text,
)
from lexer import SourceError, attach_comments, first_comment_blank, lexical_analysis
from parser import Parser
from printer import layout
from report import diff_lines, doc_tree, write_lines


def read_profiles(path="input/style.txt"):
    profiles = {}
    current = None
    for line in Path(path).read_text(encoding="ascii").splitlines():
        if not line:
            continue
        if line.startswith("[") and line.endswith("]"):
            current = line[1:-1]
            profiles[current] = {}
            continue
        key, value = line.split("=", 1)
        if key in ("width", "indent", "max_blank_lines", "comment_column"):
            value = int(value)
        elif key in ("space_around_operators", "space_after_keyword",
                     "indent_case_labels", "add_braces", "remove_parens"):
            value = value == "yes"
        profiles[current][key] = value
    return profiles


def read_sources(path="input/sources.txt"):
    source_files = []
    for line in Path(path).read_text(encoding="ascii").splitlines():
        if line.startswith("=== "):
            marker, filename, profile = line.split(" ")
            entry = {
                "header": line,
                "filename": filename,
                "profile": profile,
                "lines": [],
            }
            source_files.append(entry)
        else:
            source_files[-1]["lines"].append(line)
    return source_files


def check_comment_positions(tokens):
    for token in tokens:
        for comment in token["leading"]:
            if (token["trailing_comma"] or
                    (comment["own_line"] and not token["allowed"])):
                raise SourceError(
                    comment["line"], comment["column"],
                    "comment not allowed here",
                )


class DocumentFormatter:

    def __init__(self, profile, tokens):
        self.profile = profile
        self.tokens = tokens
        self.indent_width = profile["indent"]
        self.max_blank = profile["max_blank_lines"]
        self.spaced_operators = profile["space_around_operators"]
        self.separator = " " if self.spaced_operators else ""
        self.operator_break = LINE if self.spaced_operators else SOFTLINE
        self.keyword_gap = " " if profile["space_after_keyword"] else ""
        self.kr = profile["brace_style"] == "kr"

    def sep(self, blank):
        return concat([
            HARDLINE, *([HARDLINE] * min(blank, self.max_blank))
        ])

    def pre_blank(self, tok):
        return first_comment_blank(tok)

    def comments(self, comments, following):
        documents = []
        for i, comment in enumerate(comments):
            documents.append(text(comment["text"]))
            next_entry = (
                comments[i + 1] if i + 1 < len(comments) else following
            )
            if next_entry is None:
                continue
            if comment["own_line"]:
                documents.append(HARDLINE)
                documents.extend(
                    HARDLINE for _ in range(
                        min(next_entry["blank"], self.max_blank)
                    )
                )
            else:
                documents.append(text(" "))
        return concat(documents)

    def t(self, tok, leading=None):
        prefix = tok["leading"] if leading is None else leading
        trailing = tok["trailing"]
        return concat([
            self.comments(prefix, tok),
            text(tok["text"]),
            suffix(" ".join(comment["text"] for comment in trailing))
            if trailing else None,
        ])

    def splitting_comments(self, close):
        comments = close["leading"]
        last_own = -1
        for i, comment in enumerate(comments):
            if comment["own_line"]:
                last_own = i
        return comments[:last_own + 1], comments[last_own + 1:]

    def closing_comments(self, comments, preceding):
        if not comments:
            return None
        return concat([
            self.sep(comments[0]["blank"]) if preceding else None,
            self.comments(comments, None),
        ])

    def whole_file(self, items, end_token):
        pieces = []
        for index, item in enumerate(items):
            if index:
                pieces.append(self.sep(self.pre_blank(item["first"])))
            pieces.append(self.item(item))
        if end_token["leading"]:
            pieces.append(
                self.sep(end_token["leading"][0]["blank"]) if items else None
            )
            pieces.append(self.comments(end_token["leading"], None))
        return concat(pieces)

    def item(self, item):
        if item["tag"] == "function":
            return concat([
                self.t(item["typ"]), " ", self.t(item["name"]),
                self.list_doc(item["parameters"]), HARDLINE,
                self.block(item["body"]),
            ])
        return self.variable(item)

    def parameter(self, param):
        pieces = [self.t(param["typ"]), " ", self.t(param["name"])]
        for opening, closing in param["brackets"]:
            pieces.extend([self.t(opening), self.t(closing)])
        return concat(pieces)

    def variable(self, statement):
        pieces = [self.t(statement["typ"]), " ", self.t(statement["name"])]
        for opening, expression, closing in statement["dimensions"]:
            pieces.append(self.t(opening))
            if expression is not None:
                pieces.append(self.expr(expression, 0))
            pieces.append(self.t(closing))
        if statement["equals"] is not None:
            pieces.extend([
                self.separator, self.t(statement["equals"]),
                self.separator, self.initializer(statement["initializer"]),
            ])
        if statement["semi"] is not None:
            pieces.append(self.t(statement["semi"]))
        return concat(pieces)

    def initializer(self, entry):
        if entry["tag"] == "list":
            return self.list_doc(entry)
        return self.expr(entry, 0)

    def list_contents(self, entry):
        elements = []
        for item in entry["elements"]:
            if entry["role"] == "(" and item["tag"] == "parameter":
                elements.append(self.parameter(item))
            elif entry["role"] == "{" and item["tag"] == "list":
                elements.append(self.list_doc(item))
            else:
                elements.append(self.initializer(item) if entry["role"] == "{"
                                else self.expr(item, 0))
        return elements

    def list_force_marker(self, entry):
        first = entry["left"]["index"]
        last = entry["right"]["index"]
        any_trailing = any(
            self.tokens[index]["trailing"]
            for index in range(first, last)
        )
        return BREAK_PARENT if any_trailing else None

    def list_doc(self, entry):
        left, right = entry["left"], entry["right"]
        elements = self.list_contents(entry)
        if not elements:
            return concat([self.t(left), self.t(right)])
        separated = [SOFTLINE, elements[0]]
        for comma, element in zip(entry["commas"], elements[1:]):
            separated.extend([self.t(comma), LINE, element])
        if entry["role"] == "{":
            separated.append(if_break(",", ""))
            trailing = entry["trailing"]
            if trailing is not None and trailing["trailing"]:
                separated.append(suffix(
                    " ".join(comment["text"] for comment in trailing["trailing"])
                ))
        return group(concat([
            self.list_force_marker(entry),
            self.t(left),
            nest(self.indent_width, concat(separated)),
            SOFTLINE, self.t(right),
        ]))

    def block(self, entry):
        opening, closing = entry["left"], entry["right"]
        statements = entry["statements"]
        own, inline = self.splitting_comments(closing)
        if not statements and not own:
            return concat([self.t(opening), self.t(closing, inline)])
        body = []
        for index, statement in enumerate(statements):
            if index:
                body.append(self.sep(self.pre_blank(statement["first"])))
            else:
                body.append(HARDLINE)
            body.append(self.statement(statement))
        body.append(self.closing_comments(own, bool(statements)))
        return concat([
            self.t(opening), nest(self.indent_width, concat(body)),
            HARDLINE, self.t(closing, inline),
        ])

    def body(self, entry):
        if entry["tag"] == "block":
            return concat([
                " " if self.kr else HARDLINE, self.block(entry),
            ])
        if self.profile["add_braces"]:
            return concat([
                " " if self.kr else HARDLINE, "{",
                nest(self.indent_width, concat([HARDLINE, self.statement(entry)])),
                HARDLINE, "}",
            ])
        return nest(self.indent_width, concat([HARDLINE, self.statement(entry)]))

    def simple(self, item):
        if item["tag"] == "assign":
            return concat([
                self.expr(item["left"], 0), self.separator,
                self.t(item["op"]), self.separator,
                self.expr(item["right"], 0),
            ])
        return self.expr(item["expr"], 0)

    def if_statement(self, entry):
        parts = [
            self.t(entry["keyword"]), self.keyword_gap,
            self.t(entry["left"]), self.expr(entry["test"], 0),
            self.t(entry["right"]), self.body(entry["body"]),
        ]
        if entry["else_token"] is not None:
            before = entry["body"]
            separator = (
                " " if self.kr and (
                    before["tag"] == "block" or self.profile["add_braces"]
                ) else HARDLINE
            )
            parts.extend([separator, self.t(entry["else_token"])])
            alternative = entry["alternative"]
            if alternative["tag"] == "if":
                parts.extend([" ", self.if_statement(alternative)])
            else:
                parts.append(self.body(alternative))
        return concat(parts)

    def while_statement(self, entry):
        return concat([
            self.t(entry["keyword"]), self.keyword_gap,
            self.t(entry["left"]), self.expr(entry["test"], 0),
            self.t(entry["right"]), self.body(entry["body"]),
        ])

    def for_statement(self, entry):
        contents = []
        initial = entry["initial"]
        if initial is not None:
            contents.append(
                self.variable(initial) if initial["tag"] == "variable"
                else self.simple(initial)
            )
        contents.append(self.t(entry["first_semi"]))
        if entry["condition"] is not None:
            contents.extend([LINE, self.expr(entry["condition"], 0)])
        contents.append(self.t(entry["second_semi"]))
        if entry["update"] is not None:
            contents.extend([LINE, self.simple(entry["update"])])
        loop = group(align(concat(contents)))
        return concat([
            self.t(entry["keyword"]), self.keyword_gap,
            self.t(entry["left"]), loop, self.t(entry["right"]),
            self.body(entry["body"]),
        ])

    def clause(self, item):
        contents = [self.t(item["label"])]
        if item["value"] is not None:
            contents.extend([" ", self.expr(item["value"], 0)])
        contents.append(self.t(item["colon"]))
        statements = item["statements"]
        if statements:
            inner = [HARDLINE, self.statement(statements[0])]
            for statement in statements[1:]:
                inner.extend([
                    self.sep(self.pre_blank(statement["first"])),
                    self.statement(statement),
                ])
            contents.append(nest(self.indent_width, concat(inner)))
        return concat(contents)

    def switch_statement(self, entry):
        closing = entry["closing"]
        clauses = entry["clauses"]
        own, inline = self.splitting_comments(closing)
        header = [
            self.t(entry["keyword"]), self.keyword_gap,
            self.t(entry["left"]), self.expr(entry["test"], 0),
            self.t(entry["right"]), " " if self.kr else HARDLINE,
            self.t(entry["opening"]),
        ]
        if not clauses and not own:
            return concat([header, self.t(closing, inline)])
        inner = []
        for index, clause in enumerate(clauses):
            inner.append(
                self.sep(self.pre_blank(clause["first"])) if index else HARDLINE
            )
            inner.append(self.clause(clause))
        inner.append(self.closing_comments(own, bool(clauses)))
        extra = self.indent_width if self.profile["indent_case_labels"] else 0
        return concat([
            header, nest(extra, concat(inner)),
            HARDLINE, self.t(closing, inline),
        ])

    def statement(self, item):
        tag = item["tag"]
        if tag == "block":
            return self.block(item)
        if tag == "variable":
            return self.variable(item)
        if tag == "simple_stmt":
            return concat([self.simple(item["value"]), self.t(item["semi"])])
        if tag == "return":
            contents = [self.t(item["keyword"])]
            if item["expr"] is not None:
                contents.extend([" ", self.expr(item["expr"], 0)])
            return concat([contents, self.t(item["semi"])])
        if tag == "flow":
            return concat([self.t(item["keyword"]), self.t(item["semi"])])
        if tag == "if":
            return self.if_statement(item)
        if tag == "while":
            return self.while_statement(item)
        if tag == "for":
            return self.for_statement(item)
        if tag == "switch":
            return self.switch_statement(item)
        raise ValueError(f"unexpected statement: {tag}")

    def opened(self, entry, minimum):
        while self.profile["remove_parens"] and entry["tag"] == "paren":
            inner = entry["inner"]
            if self.level(inner) < minimum:
                break
            left, right = entry["left"], entry["right"]
            if left["leading"] or right["leading"]:
                break
            inner_first = self.first_token(inner)
            inner_last = self.last_token(inner)
            if left["trailing"]:
                inner_first["trailing"][:0] = left["trailing"]
                left["trailing"] = []
            if right["trailing"]:
                inner_last["trailing"].extend(right["trailing"])
                right["trailing"] = []
            entry = inner
        return entry

    def level(self, entry):
        return entry.get("level", 8)

    def first_token(self, entry):
        return entry["first"]

    def last_token(self, entry):
        tag = entry["tag"]
        if tag == "primary":
            return entry["value"]
        if tag == "paren":
            return entry["right"]
        if tag == "unary":
            return self.last_token(entry["operand"])
        if tag == "binary":
            return self.last_token(entry["right"])
        if tag == "conditional":
            return self.last_token(entry["no"])
        if tag == "call":
            return entry["arguments"]["right"]
        if tag == "index":
            return entry["right"]
        if tag == "member":
            return entry["member"]
        raise ValueError(tag)

    def binary(self, entry):
        precedence = entry["level"]
        operators = []
        operands = []
        current = entry
        while current["tag"] == "binary" and current["level"] == precedence:
            operators.append(current["op"])
            operands.append(current["right"])
            current = self.opened(current["left"], precedence)
        operators.reverse()
        operands.reverse()
        contents = []
        for op, operand in zip(operators, operands):
            contents.extend([
                self.operator_break, self.t(op),
                self.separator, self.expr(operand, precedence + 1),
            ])
        return group(concat([
            self.expr(current, precedence),
            nest(self.indent_width, concat(contents)),
        ]))

    def conditional(self, entry):
        contents = []
        current = entry
        while True:
            contents.extend([
                self.operator_break, self.t(current["question"]),
                self.separator, self.expr(current["yes"], 0),
                self.operator_break, self.t(current["colon"]),
                self.separator,
            ])
            following = self.opened(current["no"], 0)
            if following["tag"] != "conditional":
                contents.append(self.expr(following, 0))
                break
            contents.append(self.expr(following["test"], 1))
            current = following
        return group(concat([
            self.expr(entry["test"], 1),
            nest(self.indent_width, concat(contents)),
        ]))

    def postfix_piece(self, entry):
        tag = entry["tag"]
        if tag == "call":
            return self.list_doc(entry["arguments"])
        if tag == "index":
            return concat([
                self.t(entry["left"]), self.expr(entry["index"], 0),
                self.t(entry["right"]),
            ])
        if tag == "member":
            return concat([self.t(entry["dot"]), self.t(entry["member"])])
        raise ValueError(tag)

    def postfix(self, entry):
        operators = []
        current = entry
        while current["tag"] in ("call", "index", "member"):
            operators.append(current)
            current = self.opened(current["target"], 8)
        operators.reverse()
        segments = [[]]
        for operation in operators:
            if operation["tag"] == "member":
                segments.append([])
            segments[-1].append(operation)
        segments_with_call = [
            index for index, segment in enumerate(segments)
            if index > 0 and any(part["tag"] == "call" for part in segment)
        ]
        head = self.expr(current, 8)
        if len(segments_with_call) < 2:
            return concat([
                head, *[self.postfix_piece(op) for op in operators],
            ])
        split_at = segments_with_call[0]
        preceding = [
            self.postfix_piece(op)
            for segment in segments[:split_at] for op in segment
        ]
        following = []
        for segment in segments[split_at:]:
            following.append(SOFTLINE)
            following.extend(self.postfix_piece(op) for op in segment)
        return group(concat([
            head, *preceding, nest(self.indent_width, concat(following)),
        ]))

    def expr(self, entry, minimum):
        entry = self.opened(entry, minimum)
        tag = entry["tag"]
        if tag == "primary":
            return self.t(entry["value"])
        if tag == "paren":
            return concat([
                self.t(entry["left"]), self.expr(entry["inner"], 0),
                self.t(entry["right"]),
            ])
        if tag == "unary":
            return concat([
                self.t(entry["op"]), self.expr(entry["operand"], 8),
            ])
        if tag == "binary":
            return self.binary(entry)
        if tag == "conditional":
            return self.conditional(entry)
        if tag in ("call", "index", "member"):
            return self.postfix(entry)
        raise ValueError(f"unexpected expression: {tag}")


def render_once(lines, profile):
    tokens, comments, items = lexical_analysis(lines)
    attach_comments(tokens, comments, items)
    syntax = Parser(tokens).parse()
    check_comment_positions(tokens)
    builder = DocumentFormatter(profile, tokens)
    first_function = next((item for item in syntax if item["tag"] == "function"), None)
    if not syntax and not tokens[-1]["leading"]:
        return {
            "lines": [], "comments": comments, "document": None,
            "first_function": None,
        }
    document = builder.whole_file(syntax, tokens[-1])
    formatted = layout(document, profile)
    return {
        "lines": formatted,
        "comments": comments,
        "document": document,
        "first_function": first_function,
        "builder": builder,
    }


def first_differing_line(a, b):
    for i, (left, right) in enumerate(zip(a, b), 1):
        if left != right:
            return i
    return min(len(a), len(b)) + 1


def format_source(file, profiles):
    profile = profiles[file["profile"]]
    original = [line.rstrip(" ") for line in file["lines"]]
    result = {**file, "original": original, "error": None}
    try:
        first = render_once(file["lines"], profile)
    except SourceError as error:
        result.update({
            "formatted": original, "error": error,
            "idempotency": f"{file['filename']}: skipped (syntax error)",
            "diagnostics": [
                f"{file['filename']}:{error.line}:{error.column}: "
                f"error: {error.message}"
            ],
        })
        return result

    result["first"] = first
    result["formatted"] = first["lines"]
    try:
        second = render_once(first["lines"], profile)
    except SourceError as error:
        result["idempotency"] = (
            f"{file['filename']}: unstable (second pass: "
            f"{error.line}:{error.column}: {error.message})"
        )
    else:
        if first["lines"] == second["lines"]:
            result["idempotency"] = f"{file['filename']}: stable"
        else:
            difference = first_differing_line(first["lines"], second["lines"])
            result["idempotency"] = (
                f"{file['filename']}: unstable at line {difference}"
            )
    diagnostics = []
    for lineno, line in enumerate(first["lines"], 1):
        if len(line) > profile["width"]:
            diagnostics.append(
                f"{file['filename']}:{lineno}: warning: line too long "
                f"({len(line)} > {profile['width']})"
            )
    result["diagnostics"] = diagnostics
    return result


def output_formatted(results):
    lines = []
    for item in results:
        lines.append(item["header"])
        lines.extend(item["formatted"])
    return lines


def output_idempotency(results):
    return [item["idempotency"] for item in results]


def output_diagnostics(results):
    rows = []
    for item in results:
        rows.extend(item["diagnostics"])
    return rows if rows else ["no diagnostics"]


def output_tree(results):
    lines = []
    for item in results:
        lines.append(f"=== {item['filename']}")
        if item["error"] is not None:
            lines.append("syntax error")
            continue
        first = item["first"]
        formatted = first["lines"]
        document = first["document"]
        groups = list(all_groups(document)) if document else []
        lines.append(
            f"metrics lines={len(formatted)} "
            f"longest={max(map(len, formatted), default=0)} "
            f"comments={len(first['comments'])} "
            f"groups={len(groups)} "
            f"broken={sum(g['mode'] in ('break', 'forced') for g in groups)} "
            f"forced={sum(g['mode'] == 'forced' for g in groups)}"
        )
        if first["first_function"] is None:
            lines.append("no function")
        else:
            function = first["first_function"]
            lines.append(f"function {function['name']['text']}")
            function_doc = first["builder"].item(function)
            layout(function_doc, read_profile(item))
            lines.extend(doc_tree(function_doc))
    return lines


def read_profile(file):
    return file["profile_values"]


def output_changes(results):
    lines = []
    for item in results:
        lines.append(f"=== {item['filename']}")
        if item["error"] is not None:
            lines.append("skipped (syntax error)")
        else:
            lines.extend(diff_lines(item["original"], item["formatted"]))
    return lines


def main():
    profiles = read_profiles()
    sources = read_sources()
    results = []
    for file in sources:
        file["profile_values"] = profiles[file["profile"]]
        results.append(format_source(file, profiles))
    write_lines("formatted.txt", output_formatted(results))
    write_lines("idempotency.txt", output_idempotency(results))
    write_lines("diagnostics.txt", output_diagnostics(results))
    write_lines("doc_tree.txt", output_tree(results))
    write_lines("changes.txt", output_changes(results))


if __name__ == "__main__":
    main()

from lexer import ASSIGNMENT, SourceError, TYPES


PRECEDENCE = {
    "||": 1, "&&": 2,
    "==": 3, "!=": 3,
    "<": 4, "<=": 4, ">": 4, ">=": 4,
    "+": 5, "-": 5,
    "*": 6, "/": 6, "%": 6,
}


def node(tag, first, **props):
    return {"tag": tag, "first": first, **props}


class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.cursor = 0

    def peek(self):
        return self.tokens[self.cursor]

    def at(self, symbol):
        return self.peek()["text"] == symbol

    def fail(self, expected):
        actual = self.peek()
        found = "end of file" if actual["kind"] == "end" else f"'{actual['text']}'"
        raise SourceError(
            actual["line"], actual["column"],
            f"expected {expected}, found {found}",
        )

    def take(self, symbol):
        if not self.at(symbol):
            self.fail(f"'{symbol}'")
        token = self.peek()
        self.cursor += 1
        return token

    def take_identifier(self):
        if self.peek()["kind"] != "identifier":
            self.fail("identifier")
        token = self.peek()
        self.cursor += 1
        return token

    def take_type(self):
        if self.peek()["text"] not in TYPES:
            self.fail("type")
        token = self.peek()
        self.cursor += 1
        return token

    def is_type(self):
        return self.peek()["text"] in TYPES

    def allow(self, tok):
        tok["allowed"] = True

    def parse(self):
        result = []
        while self.peek()["kind"] != "end":
            result.append(self.item())
        return result

    def item(self):
        typ = self.take_type()
        self.allow(typ)
        name = self.take_identifier()
        if self.at("("):
            parameters = self.list_of("(", ")", self.parameter, False)
            body = self.block()
            return node("function", typ, typ=typ, name=name,
                        parameters=parameters, body=body)
        return self.var_remainder(typ, name, semicolon=True)

    def parameter(self):
        typ = self.take_type()
        name = self.take_identifier()
        brackets = []
        while self.at("["):
            opening = self.take("[")
            closing = self.take("]")
            brackets.append((opening, closing))
        return node("parameter", typ, typ=typ, name=name, brackets=brackets)

    def var_remainder(self, typ, name, semicolon):
        dimensions = []
        while self.at("["):
            opening = self.take("[")
            expression = None if self.at("]") else self.expression()
            closing = self.take("]")
            dimensions.append((opening, expression, closing))
        equals = self.take("=") if self.at("=") else None
        initializer = self.initializer() if equals is not None else None
        semi = self.take(";") if semicolon else None
        return node("variable", typ, typ=typ, name=name, dimensions=dimensions,
                    equals=equals, initializer=initializer, semi=semi)

    def initializer(self):
        return (self.list_of("{", "}", self.initializer, True)
                if self.at("{") else self.expression())

    def list_of(self, opening, closing, element, trailing):
        left = self.take(opening)
        contents, commas = [], []
        final_comma = None
        if not self.at(closing):
            first = element()
            self.allow(first["first"])
            contents.append(first)
            while self.at(","):
                comma = self.take(",")
                if trailing and self.at(closing):
                    comma["trailing_comma"] = True
                    final_comma = comma
                    break
                commas.append(comma)
                item = element()
                self.allow(item["first"])
                contents.append(item)
        right = self.take(closing)
        return node("list", left, left=left, right=right, elements=contents,
                    commas=commas, trailing=final_comma, role=opening)

    def block(self):
        left = self.take("{")
        statements = []
        while not self.at("}") and self.peek()["kind"] != "end":
            statement = self.statement()
            self.allow(statement["first"])
            statements.append(statement)
        right = self.take("}")
        self.allow(right)
        return node("block", left, left=left, right=right,
                    statements=statements)

    def statement(self):
        tok = self.peek()
        if self.at("{"):
            return self.block()
        if self.is_type():
            typ = self.take_type()
            name = self.take_identifier()
            return self.var_remainder(typ, name, True)
        if self.at("if"):
            return self.if_statement()
        if self.at("while"):
            return self.while_statement()
        if self.at("for"):
            return self.for_statement()
        if self.at("switch"):
            return self.switch_statement()
        if self.at("return"):
            keyword = self.take("return")
            expr = None if self.at(";") else self.expression()
            semi = self.take(";")
            return node("return", keyword, keyword=keyword, expr=expr, semi=semi)
        if self.at("break") or self.at("continue"):
            keyword = self.peek()
            self.cursor += 1
            semi = self.take(";")
            return node("flow", keyword, keyword=keyword, semi=semi)
        expression = self.simple()
        semi = self.take(";")
        return node("simple_stmt", expression["first"], value=expression, semi=semi)

    def body(self):
        result = self.statement()
        if result["tag"] != "block" and result["tag"] != "if_else_if":
            self.allow(result["first"])
        return result

    def if_statement(self):
        keyword = self.take("if")
        left = self.take("(")
        condition = self.expression()
        right = self.take(")")
        body = self.body()
        else_token = self.take("else") if self.at("else") else None
        alternative = None
        if else_token is not None:
            if self.at("if"):
                alternative = self.if_statement()
                alternative["first"]["allowed"] = False
            else:
                alternative = self.body()
        return node("if", keyword, keyword=keyword, left=left, test=condition,
                    right=right, body=body, else_token=else_token,
                    alternative=alternative)

    def while_statement(self):
        keyword = self.take("while")
        left = self.take("(")
        condition = self.expression()
        right = self.take(")")
        body = self.body()
        return node("while", keyword, keyword=keyword, left=left,
                    test=condition, right=right, body=body)

    def for_statement(self):
        keyword = self.take("for")
        left = self.take("(")
        if self.at(";"):
            initial = None
        elif self.is_type():
            typ = self.take_type()
            name = self.take_identifier()
            initial = self.var_remainder(typ, name, False)
        else:
            initial = self.simple()
        first_semi = self.take(";")
        condition = None if self.at(";") else self.expression()
        second_semi = self.take(";")
        update = None if self.at(")") else self.simple()
        right = self.take(")")
        body = self.body()
        return node("for", keyword, keyword=keyword, left=left, initial=initial,
                    first_semi=first_semi, condition=condition,
                    second_semi=second_semi, update=update, right=right, body=body)

    def switch_statement(self):
        keyword = self.take("switch")
        left = self.take("(")
        test = self.expression()
        right = self.take(")")
        opening = self.take("{")
        clauses = []
        while self.at("case") or self.at("default"):
            label = self.peek()
            self.cursor += 1
            self.allow(label)
            value = self.expression() if label["text"] == "case" else None
            colon = self.take(":")
            statements = []
            while (not self.at("case") and not self.at("default")
                   and not self.at("}") and self.peek()["kind"] != "end"):
                stmt = self.statement()
                self.allow(stmt["first"])
                statements.append(stmt)
            clauses.append(node("clause", label, label=label,
                                value=value, colon=colon, statements=statements))
        closing = self.take("}")
        self.allow(closing)
        return node("switch", keyword, keyword=keyword, left=left, test=test,
                    right=right, opening=opening, closing=closing, clauses=clauses)

    def simple(self):
        left = self.expression()
        if self.peek()["text"] in ASSIGNMENT:
            operator = self.peek()
            self.cursor += 1
            right = self.expression()
            return node("assign", left["first"], left=left, op=operator, right=right)
        return node("expr_stmt", left["first"], expr=left)

    def expression(self):
        condition = self.binary(1)
        if self.at("?"):
            question = self.take("?")
            yes = self.expression()
            colon = self.take(":")
            no = self.expression()
            return node("conditional", condition["first"], test=condition,
                        question=question, yes=yes, colon=colon, no=no, level=0)
        return condition

    def binary(self, precedence):
        if precedence > 6:
            return self.unary()
        left = self.binary(precedence + 1)
        while PRECEDENCE.get(self.peek()["text"]) == precedence:
            operator = self.peek()
            self.cursor += 1
            right = self.binary(precedence + 1)
            left = node("binary", left["first"], left=left, op=operator,
                        right=right, level=precedence)
        return left

    def unary(self):
        if self.at("-") or self.at("!"):
            operator = self.peek()
            self.cursor += 1
            operand = self.unary()
            return node("unary", operator, op=operator, operand=operand, level=7)
        target = self.primary()
        while True:
            if self.at("("):
                args = self.list_of("(", ")", self.expression, False)
                target = node("call", target["first"], target=target,
                              arguments=args, level=8)
            elif self.at("["):
                left = self.take("[")
                index = self.expression()
                right = self.take("]")
                target = node("index", target["first"], target=target,
                              left=left, index=index, right=right, level=8)
            elif self.at("."):
                dot = self.take(".")
                member = self.take_identifier()
                target = node("member", target["first"], target=target,
                              dot=dot, member=member, level=8)
            else:
                break
        return target

    def primary(self):
        tok = self.peek()
        if tok["kind"] in ("identifier", "number", "string") or tok["text"] in (
                "true", "false"):
            self.cursor += 1
            return node("primary", tok, value=tok, level=8)
        if self.at("("):
            left = self.take("(")
            inner = self.expression()
            right = self.take(")")
            return node("paren", left, left=left, inner=inner,
                        right=right, level=8)
        self.fail("expression")

def fits(remaining, candidate, rest):
    if remaining < 0:
        return False
    check = [candidate]
    next_existing = len(rest) - 1
    while True:
        if not check:
            if next_existing < 0:
                return True
            check.append(rest[next_existing])
            next_existing -= 1
        indent, mode, doc = check.pop()
        kind = doc["kind"]
        if kind == "text":
            remaining -= len(doc["value"])
        elif kind == "if_break":
            remaining -= len(doc["broken"] if mode == "break" else doc["flat"])
        elif kind == "line":
            if mode == "break":
                return True
            remaining -= 1
        elif kind == "softline":
            if mode == "break":
                return True
        elif kind == "hardline":
            return True
        elif kind == "concat":
            check.extend(
                (indent, mode, child) for child in reversed(doc["items"])
            )
        elif kind == "group":
            child_mode = "break" if doc["forced"] else mode
            check.append((indent, child_mode, doc["child"]))
        elif kind in ("nest", "align"):
            check.append((indent, mode, doc["child"]))
        if remaining < 0:
            return False


def layout(document, profile):
    width = profile["width"]
    column = profile["comment_column"]
    result = []
    current = ""
    pending = []
    stack = [(0, "break", document)]

    def finalize():
        nonlocal current
        output = current.rstrip(" ")
        if pending:
            comment_text = " ".join(pending)
            if (column > 0 and len(output) < column - 1
                    and column - 1 + len(comment_text) <= width):
                output += " " * (column - 1 - len(output)) + comment_text
            else:
                output += " " + comment_text
            pending.clear()
        result.append(output)

    while stack:
        indentation, mode, doc = stack.pop()
        kind = doc["kind"]
        if kind == "text":
            current += doc["value"]
        elif kind == "if_break":
            current += doc["broken"] if mode == "break" else doc["flat"]
        elif kind == "line":
            if mode == "flat":
                current += " "
            else:
                finalize()
                current = " " * indentation
        elif kind == "softline":
            if mode == "break":
                finalize()
                current = " " * indentation
        elif kind == "hardline":
            finalize()
            current = " " * indentation
        elif kind == "concat":
            stack.extend(
                (indentation, mode, child)
                for child in reversed(doc["items"])
            )
        elif kind == "nest":
            stack.append((indentation + doc["amount"], mode, doc["child"]))
        elif kind == "align":
            stack.append((len(current), mode, doc["child"]))
        elif kind == "suffix":
            pending.append(doc["value"])
        elif kind == "break_parent":
            pass
        elif kind == "group":
            if mode == "flat":
                next_mode = "flat"
            elif doc["forced"]:
                next_mode = "forced"
            elif fits(width - len(current), (indentation, "flat", doc["child"]), stack):
                next_mode = "flat"
            else:
                next_mode = "break"
            doc["mode"] = next_mode
            stack.append(
                (indentation, "flat" if next_mode == "flat" else "break",
                 doc["child"])
            )
        else:
            raise ValueError(f"unknown document kind: {kind}")
    finalize()
    return result

from pathlib import Path


def doc_tree(document, depth=0):
    kind = document["kind"]
    prefix = "  " * depth
    if kind == "concat":
        result = []
        for child in document["items"]:
            result.extend(doc_tree(child, depth))
        return result
    if kind == "text":
        return [prefix + 'text "' + document["value"] + '"']
    if kind == "suffix":
        return [prefix + 'suffix "' + document["value"] + '"']
    if kind == "if_break":
        return [
            prefix + 'if_break "' + document["broken"]
            + '" "' + document["flat"] + '"'
        ]
    if kind == "group":
        return [prefix + f"group {document['mode']}"] + doc_tree(
            document["child"], depth + 1
        )
    if kind == "nest":
        return [prefix + f"nest {document['amount']}"] + doc_tree(
            document["child"], depth + 1
        )
    if kind == "align":
        return [prefix + "align"] + doc_tree(document["child"], depth + 1)
    return [prefix + kind]


def diff_lines(original, formatted):
    n, m = len(original), len(formatted)
    table = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if original[i] == formatted[j]:
                table[i][j] = table[i + 1][j + 1] + 1
            else:
                table[i][j] = max(table[i + 1][j], table[i][j + 1])
    i = j = 0
    hunks = []
    current = None
    deleted = inserted = 0
    while i < n or j < m:
        if i < n and j < m and original[i] == formatted[j]:
            if current is not None:
                hunks.append(current)
                current = None
            i += 1
            j += 1
            continue
        if current is None:
            current = {"start_old": i, "start_new": j,
                       "deletes": 0, "inserts": 0, "lines": []}
        if j == m or (i < n and table[i + 1][j] >= table[i][j + 1]):
            current["deletes"] += 1
            deleted += 1
            current["lines"].append("-" + original[i])
            i += 1
        else:
            current["inserts"] += 1
            inserted += 1
            current["lines"].append("+" + formatted[j])
            j += 1
    if current is not None:
        hunks.append(current)

    result = [f"hunks={len(hunks)} deleted={deleted} inserted={inserted}"]
    for hunk in hunks:
        count_old = hunk["deletes"]
        count_new = hunk["inserts"]
        start_old = hunk["start_old"] + (1 if count_old else 0)
        start_new = hunk["start_new"] + (1 if count_new else 0)
        result.append(
            f"@@ -{start_old},{count_old} +{start_new},{count_new} @@"
        )
        result.extend(hunk["lines"])
    return result


def write_lines(filename, lines):
    target = Path("output") / filename
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text("\n".join(lines) + "\n" if lines else "", encoding="ascii")
